CREATE TABLE products (id SERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, category VARCHAR(50), price DECIMAL(10,2), inventory INT, description TEXT); CREATE TABLE customers (id SERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(100) UNIQUE, signup_date DATE, last_login TIMESTAMP); CREATE TABLE orders (id SERIAL PRIMARY KEY, customer_id INT REFERENCES customers(id), order_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP, total_amount DECIMAL(10,2), status VARCHAR(20)); CREATE TABLE order_items (id SERIAL PRIMARY KEY, order_id INT REFERENCES orders(id), product_id INT REFERENCES products(id), quantity INT, price DECIMAL(10,2)); INSERT INTO products (name, category, price, inventory, description) VALUES ('Laptop Pro', 'Electronics', 1299.99, 50, 'High-performance laptop'), ('Smartphone X', 'Electronics', 899.99, 100, 'Latest smartphone'), ('Wireless Headphones', 'Audio', 199.99, 200, 'Noise-cancelling headphones'), ('Office Chair', 'Furniture', 249.99, 30, 'Ergonomic chair'), ('Coffee Maker', 'Appliances', 89.99, 75, 'Programmable coffee maker'); INSERT INTO customers (name, email, signup_date, last_login) VALUES ('John Smith', 'john.smith@example.com', '2023-01-15', '2023-06-10 14:30:00'), ('Emma Johnson', 'emma.j@example.com', '2023-02-20', '2023-06-12 09:15:00'), ('Michael Brown', 'michael.b@example.com', '2023-03-05', '2023-06-11 18:45:00'), ('Sarah Wilson', 'sarah.w@example.com', '2023-04-10', '2023-06-09 11:20:00'), ('David Lee', 'david.lee@example.com', '2023-05-01', '2023-06-08 16:10:00'); INSERT INTO orders (customer_id, order_date, total_amount, status) VALUES (1, '2023-05-15 10:30:00', 1499.98, 'Completed'), (2, '2023-05-20 14:45:00', 899.99, 'Shipped'), (3, '2023-05-25 09:15:00', 449.98, 'Processing'), (4, '2023-06-01 16:20:00', 89.99, 'Completed'), (5, '2023-06-05 11:30:00', 2199.97, 'Shipped'); INSERT INTO order_items (order_id, product_id, quantity, price) VALUES (1, 1, 1, 1299.99), (1, 3, 1, 199.99), (2, 2, 1, 899.99), (3, 3, 1, 199.99), (3, 4, 1, 2